// 합이 S 이하인 가장 긴 연속 구간 (모든 원소가 양수)
int l = 0; long long sum = 0; int best = 0;
for (int r = 0; r < n; r++) {
    sum += a[r];
    while (sum > S) sum -= a[l++];      // 왼쪽 끝을 당겨 조건을 맞춘다
    best = max(best, r - l + 1);
}

